<#
.SYNOPSIS
  Builds the tween probe fixtures in tests\fixtures\tween-probes with the real
  Flash 8 IDE, then converts them to XFL with JPEXS FLA Convert.

.DESCRIPTION
  For each NAME: writes target\oracle\gen\tween-probe-NAME.jsfl (a path prelude
  plus builders\NAME.jsfl), runs it through tools\oracle\run-jsfl.ps1 (which
  takes and releases the Flash lock target\flash8.lock), and converts
  tween-probes\NAME\NAME.fla to tween-probes\NAME\xfl. The builders save the
  FLA, reopen it and publish tween-probes\NAME\flash8.swf from the reopened
  file (MANIFEST J15). No Test Movie trace is captured (the probes have no
  scripts).

.EXAMPLE
  powershell -NoProfile -ExecutionPolicy Bypass -File C:\dev\jazari\tests\fixtures\tween-probes\builders\build.ps1 -Names matrices
#>
param(
    [Parameter(Mandatory = $true)] [string[]] $Names,
    [int] $TimeoutSec = 240,
    [string] $Jar = 'C:\dev\tools\jpexs-fla-convert-3.0.0\fla_convert.jar'
)
$ErrorActionPreference = 'Stop'
$repo = (Resolve-Path -LiteralPath (Join-Path $PSScriptRoot '..\..\..\..')).Path
$oracle = Join-Path $repo 'tools\oracle'
. (Join-Path $oracle 'flash-lock.ps1')
$root = Join-Path $repo 'tests\fixtures\tween-probes'
$genDir = Join-Path $repo 'target\oracle\gen'
$logDir = Join-Path $repo 'target\oracle\logs'
New-Item -ItemType Directory -Force $genDir, $logDir | Out-Null
$cmd = Get-Command java -ErrorAction SilentlyContinue
$Java = if ($cmd) { $cmd.Source } else { 'C:\Program Files\Eclipse Adoptium\jdk-21.0.12.101-hotspot\bin\java.exe' }

$Names = @($Names | ForEach-Object { $_ -split ',' } | ForEach-Object { $_.Trim() } | Where-Object { $_ })
foreach ($n in $Names) {
    $builder = Join-Path $PSScriptRoot "$n.jsfl"
    if (-not (Test-Path -LiteralPath $builder)) { throw "no builder $builder" }
    $dir = Join-Path $root $n
    New-Item -ItemType Directory -Force $dir | Out-Null
    $log = Join-Path $logDir "tween-probe-$n.log"
    $prelude = @(
        "// Generated by tests/fixtures/tween-probes/builders/build.ps1 from $n.jsfl; do not edit.",
        "var JZ_OUT = `"$(ConvertTo-FileUri $dir)/`";",
        "var JZ_LOG = `"$(ConvertTo-FileUri $log)`";",
        ''
    ) -join "`r`n"
    $gen = Join-Path $genDir "tween-probe-$n.jsfl"
    [byte[]] $bytes = [System.Text.Encoding]::ASCII.GetBytes($prelude) + [System.IO.File]::ReadAllBytes($builder)
    [System.IO.File]::WriteAllBytes($gen, $bytes)
    & powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $oracle 'run-jsfl.ps1') `
        -Script $gen -Log $log -TimeoutSec $TimeoutSec
    if ($LASTEXITCODE -ne 0) { Write-Host "$n : BUILD FAILED (launcher exit $LASTEXITCODE)"; continue }
    $xfl = Join-Path $dir 'xfl'
    if (Test-Path $xfl) { Remove-Item -Recurse -Force $xfl }
    $ErrorActionPreference = 'Continue'
    $conv = & $Java -jar $Jar convert --format CS5 --container xfl --charset WINDOWS-1256 (Join-Path $dir "$n.fla") $xfl 2>&1 |
            ForEach-Object { "$_" } | Select-Object -Last 1
    $ErrorActionPreference = 'Stop'
    Write-Host "$n : JPEXS: $conv"
}
